const LIMIT = 200001;
const sieve = new Uint8Array(LIMIT);
sieve[0] = 1;
sieve[1] = 1;

for (let i = 2; i * i < LIMIT; i++) {
  if (!sieve[i]) {
    for (let j = i * i; j < LIMIT; j += i) {
      sieve[j] = 1;
    }
  }
}

let count = 0;
let sum = 0n;
for (let p = 100000; p <= 200000; p++) {
  if (!sieve[p]) {
    count++;
    sum += BigInt(p);
  }
}

console.log(`Anzahl der Primzahlen: ${count}`);
console.log(`Summe der Primzahlen:   ${sum.toString()}`);
